/* Offline application UI. All persistent data stays on this device. */
'use strict';
const E=KilalaoEngine,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{data=JSON.parse(localStorage.getItem('kilalao-v1')||'{}');}catch{data={};}
const isRecord=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
if(!isRecord(data))data={};
if(!isRecord(data.sessions))data.sessions={};
if(!isRecord(data.stats))data.stats={};
for(const key of ['learned','favorites'])data[key]=Array.isArray(data[key])?[...new Set(data[key].filter(id=>CATALOG.some(g=>g.id===id)))]:[];
for(const [id,stats] of Object.entries(data.stats))if(!isRecord(stats)||!Number.isFinite(stats.wins)||stats.wins<0||!Array.isArray(stats.seeds))delete data.stats[id];
let current=null,history=[],selected=null,pick=null,slot=0,cardsSelected=[],guess=[0,1,2,3],brush=1,activeTab='play',filter='All',search='',toastTimer;
const arrayLast=a=>a[a.length-1];
const colors=['#3d86ab','#d76c51','#d7b450','#789a67','#9a7bb3','#2e5751'],COLOR_NAMES=['blue','red','gold','green','purple','dark green'];
function persist(){try{localStorage.setItem('kilalao-v1',JSON.stringify(data));}catch{toast('Device storage is full. Progress could not be saved.');}}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
// Screen changes fade in; opacity keeps the fixed dock anchored to the viewport.
function enterScreen(){const app=$('#app');app.classList.remove('screen-enter');void app.offsetWidth;app.classList.add('screen-enter');}
const demoOn=()=>typeof Demo!=='undefined'&&Demo.active();
function saveGame(){if(!current||demoOn())return;data.sessions[current.id]={state:current,history:history.slice(-60)};persist();}
function recordCompletion(){
 if(!current?.won||demoOn())return;
 let stats=data.stats[current.id]||(data.stats[current.id]={wins:0,last:null,seeds:[]}),key=current.mode+':'+current.seed;
 if(!stats.seeds.includes(key)){stats.wins++;stats.last=new Date().toISOString();stats.seeds.push(key);stats.seeds=stats.seeds.slice(-100);}
}
function transact(a,keepSelection=null){if(!current)return;let result=E.move(current,a);if(!result.ok){toast(result.msg);queueMicrotask(()=>GameMotion.reject($('#boardarea')));return false;}const before=GameMotion.snapshot($('#boardarea')),old=current;GameMotion.cancel();history.push(E.clone(current));current=result.state;selected=keepSelection;pick=null;cardsSelected=[];if(current.won){recordCompletion();toast(current.result);}saveGame();renderGame();GameMotion.play(before,$('#boardarea'),old,current,a);return true;}
// Several engine steps from one gesture (a long swipe, a painted row) animate as one.
function multiMove(actions,keep=null,oneUndo=false){if(!current)return false;let state=current,states=[];for(const a of actions){const r=E.move(state,a);if(!r.ok){if(!states.length){toast(r.msg);queueMicrotask(()=>GameMotion.reject($('#boardarea')));return false;}break;}states.push(state);state=r.state;if(state.won)break;}const before=GameMotion.snapshot($('#boardarea')),old=current;GameMotion.cancel();history.push(...(oneUndo?[old]:states).map(E.clone));current=state;selected=keep;pick=null;cardsSelected=[];if(current.won){recordCompletion();toast(current.result);}saveGame();renderGame();GameMotion.play(before,$('#boardarea'),old,current,actions[states.length-1]);return true;}
function undo(){if(!history.length){toast('No moves to undo.');return;}const before=GameMotion.snapshot($('#boardarea')),old=current;GameMotion.cancel();current=history.pop();if(current.id==='tangram')current.pieces.forEach(E.keepPieceOnBoard);selected=null;pick=null;cardsSelected=[];saveGame();renderGame();GameMotion.play(before,$('#boardarea'),old,current);}
function newGame(mode){GameMotion.cancel();current=E.init(current.id,mode||current.mode);history=[];selected=null;pick=null;slot=0;cardsSelected=[];guess=[0,1,2,3];saveGame();renderGame();}
function route(){if(demoOn())Demo.stop(true);GameMotion.cancel();let [page,id,tab]=location.hash.slice(1).split('/');if((page==='game'||page==='learn')&&id&&CATALOG.some(g=>g.id===id)){let saved=data.sessions[id];current=saved?E.clone(saved.state):E.init(id);if(id==='tangram')current.pieces.forEach(E.keepPieceOnBoard);history=saved?.history?E.clone(saved.history):[];selected=null;pick=null;slot=0;cardsSelected=[];activeTab=page==='learn'?'rules':['play','rules','strategy','research'].includes(tab)?tab:'play';renderGame();}else if(page==='progress'){current=null;renderProgress();}else{current=null;renderHome(page==='learn');}enterScreen();window.scrollTo(0,0);}
function showTab(tab){if(demoOn())Demo.stop(true);GameMotion.cancel();saveGame();activeTab=tab;window.history.pushState(null,'','#game/'+current.id+(tab==='play'?'':'/'+tab));renderGame();enterScreen();window.scrollTo(0,0);}
function navigateBack(){if(current&&activeTab!=='play'){showTab('play');return true;}if(current||location.hash&&location.hash!=='#home'){location.hash='home';return true;}return false;}
function setNav(page){document.querySelectorAll('nav a').forEach(a=>{const active=a.id==='nav-'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function svg(content,w=160,h=110){return `<svg viewBox="0 0 ${w} ${h}" aria-hidden="true">${content}</svg>`;}
function artwork(g){let a=g.art,co='#153d35',re='#d76c51',li='#9dba68';let rect=(x,y,w,h,f=co,rad=4)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rad}" fill="${f}"/>`,dot=(x,y,r=5,f=co)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${f}"/>`,line=(x,y,xx,yy,f=co)=>`<path d="M${x} ${y}L${xx} ${yy}" fill="none" stroke="${f}" stroke-width="3" stroke-linecap="round"/>`;
 if(a==='hanoi')return svg(line(80,15,80,92,'#aab58d')+rect(24,87,112,7,co)+[0,1,2,3].map(i=>rect(51-i*9,36+i*13,58+i*18,10,i%2?co:re)).join(''));
 if(a==='tree')return svg(line(40,95,40,52)+line(40,52,70,17,re)+line(40,52,90,45)+line(110,95,110,60,re)+line(110,60,90,45)+line(110,60,130,30,re)+line(22,97,140,97));
 if(a==='sprouts')return svg(`<path d="M40 70Q35 5 120 30Q145 45 85 80Q50 105 40 70" fill="none" stroke="${co}" stroke-width="3"/>`+dot(40,70)+dot(120,30)+dot(85,80)+dot(67,23,5,re));
 if(a==='sim')return svg(rangeUI(6).map(i=>{let x=80+43*Math.cos(i*Math.PI/3),y=55+43*Math.sin(i*Math.PI/3);return rangeUI(i).map(j=>line(x,y,80+43*Math.cos(j*Math.PI/3),55+43*Math.sin(j*Math.PI/3),(i+j)%2?re:co)).join('')+dot(x,y,6);}).join(''));
 if(a==='tangram')return svg(`<polygon points="30,20 120,20 75,65" fill="${co}"/><polygon points="30,20 75,65 30,110" fill="${re}"/><polygon points="120,20 120,65 97.5,42.5" fill="${li}"/><polygon points="75,65 97.5,42.5 120,65 97.5,87.5" fill="#d7b450"/><polygon points="120,65 120,110 75,110" fill="#789a67"/><polygon points="75,65 97.5,87.5 52.5,87.5" fill="#3d86ab"/><polygon points="30,110 52.5,87.5 97.5,87.5 75,110" fill="#9a7bb3"/>`);
 if(a==='river')return svg(`<path d="M15 80Q30 66 45 80T75 80T105 80T135 80M15 97Q30 83 45 97T75 97T105 97T135 97" stroke="#739eac" stroke-width="3" fill="none"/><path d="M44 62H116L105 76H55Z" fill="${co}"/>`+dot(73,42,10,re)+line(73,53,73,62));
 if(a==='frogs')return svg([40,80,120].map((x,i)=>dot(x,67,15,i===1?re:co)+dot(x-6,49,6,i===1?re:co)+dot(x+6,49,6,i===1?re:co)+dot(x-6,48,2,'#fff')+dot(x+6,48,2,'#fff')).join(''));
 if(a==='numbers')return svg(rect(17,25,58,58,co)+rect(85,25,58,58,re)+`<text x="46" y="65" font-size="30" text-anchor="middle" fill="#fff" font-family="Georgia">2</text><text x="114" y="65" font-size="30" text-anchor="middle" fill="#fff" font-family="Georgia">4</text>`);
 if(a==='set')return svg([25,66,107].map((x,i)=>rect(x,24,33,63,'#fffef9')+`<path d="M${x+16} 40l10 16-10 16-10-16Z" fill="${i===1?re:co}"/>`).join(''));
 if(a==='stones'||a==='mastermind')return svg(rangeUI(3).map(r=>rangeUI(r+3).map(c=>dot(38+c*20,30+r*24,8,r%2?re:co)).join('')).join(''));
 if(a==='hex')return svg(rangeUI(3).map(r=>rangeUI(4).map(c=>`<polygon points="${hexPoints(33+c*27+r*13.5,25+r*24,14)}" fill="${(r+c)%3?co:re}" stroke="#e8ecd9" stroke-width="2"/>`).join('')).join(''));
 if(a==='peg')return svg(rangeUI(4).map(r=>rangeUI(r+1).map(c=>dot(80-r*13+c*26,20+r*23,7,(r===2&&c===1)?'#b9c6a0':co)).join('')).join(''));
 return svg(rangeUI(4).map(r=>rangeUI(4).map(c=>{let k=r*4+c;if(a==='chomp'&&r>1&&c>1)return'';let f=a==='lights'?(k%3?'#e0c968':co):a==='nonogram'?(k%4===r?re:co):a==='checkers'?((r+c)%2?re:co):a==='rubik'?[co,re,li,'#d7b450'][Math.floor(k/4)]:co;let z=rect(38+c*22,12+r*22,19,19,f);if(a==='sliding'&&k===15)return'';if(['sudoku','sliding','kakuro','queens'].includes(a))z+=`<text x="${47+c*22}" y="${26+r*22}" fill="#fff" font-size="11" text-anchor="middle">${a==='queens'?(r===c?'♛':''):(k%9)+1}</text>`;return z;}).join('')).join(''));
}
function rangeUI(n){return Array.from({length:n},(_,i)=>i);}
function hexPoints(x,y,r){return rangeUI(6).map(i=>[x+r*Math.cos((i*60-30)*Math.PI/180),y+r*Math.sin((i*60-30)*Math.PI/180)].join(',')).join(' ');}
function renderHome(learn=false){document.body.classList.remove('in-game');setNav(learn?'learn':'play');let games=CATALOG.filter(g=>(filter==='All'||g.category===filter||filter==='Favorites'&&data.favorites.includes(g.id))&&[g.name,g.desc,g.math].join(' ').toLowerCase().includes(search.toLowerCase()));$('#app').innerHTML=`<section class="home-intro"><div class="eyebrow">24 families · endless discoveries</div><h1>${learn?'Find the idea<br><em>behind the game.</em>':'A little play.<br><em>A lot to discover.</em>'}</h1><p>${learn?'Rules, strategies, and research — one game at a time.':'Choose a puzzle. Explore a pattern. Make your next move.'}</p></section><div class="toolbar"><input class="search" type="search" placeholder="Search games & ideas" aria-label="Search games" value="${esc(search)}"><div class="filters" role="group" aria-label="Filter games">${['All','Strategy','Logic','Spatial','Patterns','Numbers','Favorites'].map(v=>`<button class="filter ${filter===v?'active':''}" aria-pressed="${filter===v}" data-filter="${v}">${v}</button>`).join('')}</div></div><div class="section-title"><h2>${learn?'Learning library':'Choose your game'}</h2><span class="subtle">${games.length} families</span></div><div class="cards">${games.map(g=>`<a class="card" href="#${learn?'learn':'game'}/${g.id}" style="--tint:${['#e8ecd9','#f0e3d8','#e0ebeb','#eee6ef'][Math.floor((g.number-1)/3)%4]}"><div class="card-art"><span class="card-number">${String(g.number).padStart(2,'0')}</span>${artwork(g)}</div><div class="card-body"><h3>${esc(g.name)}</h3><p>${esc(g.desc)}</p><div class="card-bottom"><span>${esc(g.category)}</span><span class="arrow" aria-hidden="true">→</span></div>${data.sessions[g.id]?'<span class="resume-label">Continue playing</span>':''}</div></a>`).join('')||'<div class="empty-state">No games match your search.</div>'}</div><p class="footer-note">Offline games and guides. No accounts, ads, or tracking. Two-player games use one device.</p>`;
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderHome(learn);});$('.search').oninput=e=>{search=e.target.value;let start=e.target.selectionStart;renderHome(learn);$('.search').focus();$('.search').setSelectionRange?.(start,start);};}
function renderGame(){const focused=document.activeElement,focusKey=['id','data-cell','data-peg','data-hole','data-number','data-guess','data-turn','data-line','data-piece','data-block','data-heap','data-card','data-tab'].map(attr=>[attr,focused?.getAttribute(attr)]).find(([,value])=>value!=null&&value!=='');let s=current,g=CATALOG.find(g=>g.id===s.id),L=LEARNING[s.id];document.body.classList.add('in-game');document.body.dataset.game=s.id;setNav(activeTab==='play'?'play':'learn');$('#app').innerHTML=`<div class="game-topbar"><a class="back" href="#${activeTab==='play'?'home':'learn'}" aria-label="Back to all games">←</a><div class="game-heading"><h1>${esc(g.name)}</h1><span>${esc(g.category)} · ${esc(g.math)}</span></div><button id="favorite" aria-label="${data.favorites.includes(s.id)?'Remove from':'Add to'} favorites" aria-pressed="${data.favorites.includes(s.id)}">${data.favorites.includes(s.id)?'★':'☆'}</button></div><div class="game-tools"><div class="game-switch" role="group" aria-label="Play or learn"><button data-tab="play" class="${activeTab==='play'?'active':''}" aria-pressed="${activeTab==='play'}">Play</button><button data-tab="rules" class="${activeTab!=='play'?'active':''}" aria-pressed="${activeTab!=='play'}">Learn the game</button></div><button id="game-updates" data-check-updates class="update-button icon-button" type="button" aria-label="Check for updates" title="Check for updates"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v11m-4.5-4.5L12 15l4.5-4.5M5 19h14"/></svg></button></div><div class="learning-tabs" ${activeTab==='play'?'hidden':''} role="group" aria-label="Learning section">${['rules','strategy','research'].map(t=>`<button data-tab="${t}" class="${activeTab===t?'active':''}" aria-pressed="${activeTab===t}">${({rules:'Rules',strategy:'Strategy',research:'Research'})[t]}</button>`).join('')}</div>${activeTab==='play'?playLayout(g,s,L):learningLayout(g,L,activeTab)}`;
 $('#favorite').onclick=()=>{let i=data.favorites.indexOf(s.id);if(i<0)data.favorites.push(s.id);else data.favorites.splice(i,1);persist();renderGame();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{showTab(b.dataset.tab);});if(activeTab==='play')bindPlay();else{$('#mark-read').onclick=()=>{if(!data.learned.includes(s.id))data.learned.push(s.id);persist();toast('Added to your learning progress.');renderGame();};$('#try-game').onclick=()=>{showTab('play');};if($('#watch-demo'))$('#watch-demo').onclick=()=>{showTab('play');Demo.start(s.id);};}if(focusKey)[...$('#app').querySelectorAll('['+focusKey[0]+']')].find(el=>el.getAttribute(focusKey[0])===focusKey[1])?.focus({preventScroll:true});}
function learningLayout(g,L,tab){let title={rules:'How to play',strategy:'Think a move ahead',research:'Behind the game'}[tab],key=tab==='rules'?'rules':tab==='strategy'?'strategy':'research';return`<section class="learning"><div class="learn-block"><span class="overline">${g.math}</span><h2>${title}</h2>${tab==='research'?L[key].map(p=>`<p>${esc(p)}</p>`).join(''):`<ol>${L[key].map(p=>`<li>${esc(p)}</li>`).join('')}</ol>`}</div>${variantNotes(g.id)}${variantLearning(L,tab)}${tab==='research'?`<div class="learn-block"><h2>Read the sources</h2><p class="subtle">Original papers, academic resources, and official rules. These links require an internet connection.</p>${L.sources.map(src=>`<a class="source-link" href="${esc(src.url)}" rel="noopener noreferrer">${esc(src.label)} ↗</a>`).join('')}</div><div class="notice">Research notes describe the cited results, not a claim that every variant or every position has been solved. A proof that a winning strategy exists may not tell you which move to make.</div>`:''}<div class="controls">${tab==='rules'&&DEMO_TEXT[g.id]?'<button class="primary" id="watch-demo">▶ Watch the demo</button>':''}<button class="${tab==='rules'?'':'primary'}" id="mark-read">${data.learned.includes(g.id)?'✓ Guide read':'Mark this guide as read'}</button><button id="try-game">Try the game →</button></div></section>`;}
function variantLearning(L,tab){if(!L.variants)return '';return `<div class="learn-block"><h2>Explore the variants</h2>${Object.entries(L.variants).map(([name,v])=>`<details ${current.mode===name?'open':''}><summary>${esc(name)}</summary>${tab==='research'?v.research.map(p=>`<p>${esc(p)}</p>`).join(''):`<ol>${v[tab].map(p=>`<li>${esc(p)}</li>`).join('')}</ol>`}${tab==='research'?v.sources.map(src=>`<a class="source-link" href="${esc(src.url)}" rel="noopener noreferrer">${esc(src.label)} ↗</a>`).join(''):''}</details>`).join('')}</div>`;}
function variantNotes(id){let notes={hanoi:'Available modes: classic three pegs, four pegs, clockwise-only cyclic moves, and adjacent-only moves. All use four disks.',nim:'The normal Nim XOR strategy does not apply unchanged to every mode. Wythoff allows equal removals from both heaps; Fibonacci Nim limits the next removal to twice the preceding one. Subtraction uses {1, 3, 4}. Kayles removes one pin or two adjacent pins. Grundy splits a heap into two unequal nonempty heaps.',sliding:'Choose the 8 or 15 Puzzle, a traffic puzzle with vehicles that move along their length, or a classic Klotski arrangement. The traffic mode is an original educational recreation, not an official Rush Hour product.',sprouts:'Draw directly between dots with your finger. Return to the same dot for a loop. Curves cannot cross or touch other dots. When both players agree that no legal curve remains, the player to move concedes.',kakuro:'This small arithmetic practice board accepts any filling satisfying every sum and no-repeat rule; it is not advertised as a uniquely solvable published Kakuro puzzle.',mastermind:'Solo mode starts with a random secret. For two players, use “Set secret” and let the code maker choose four colors privately. Repeated colors are allowed.',tangram:'This edition starts with the classic square challenge. Drag a piece, select it to rotate 45°, or flip it. The guide reveals the target subdivision.',rubik:'Both 3×3 and 2×2 cubes use real face permutations. The research about 20 face turns is specifically about 3×3 and its half-turn metric.',set:'This is an independent educational implementation of SET’s rule, using an original display. The practice goal is five valid sets.',river:'Choose farmer–wolf–goat–cabbage or three missionaries and three cannibals. Every crossing is checked against that puzzle’s safety rule.',twentyfour:'Use all four displayed integers exactly once with +, −, ×, ÷ and parentheses. Unary minus, concatenation, powers, and factorials are not enabled.'};return notes[id]?`<div class="learn-block"><h3>In this app</h3><p>${esc(notes[id])}</p></div>`:'';}
function playLayout(g,s,L){let two=['nim','chomp','domineering','clobber','hackenbush','sprouts','boxes','hex','sim'].includes(s.id),status=s.won?s.result:two?`Player ${s.player}${s.id==='domineering'?(s.player===1?' · vertical':' · horizontal'):s.id==='hex'?(s.player===1?' · top to bottom':' · left to right'):''}`:s.id==='mastermind'?`Guess ${s.guesses.length+1} of ${s.max}`:'Your move';return`<div class="game-layout"><section class="arena" aria-label="${esc(g.name)} game"><div class="position-bar"><div class="game-status" aria-live="polite"><strong class="${two?'player'+s.player:''}">${esc(status)}</strong><span>${s.moves} ${s.moves===1?'move':'moves'}</span></div>${E.MODES[s.id]?`<label class="mode-label" for="mode">Mode<select id="mode" class="mode-select">${E.MODES[s.id].map(m=>`<option ${m===s.mode?'selected':''}>${esc(m)}</option>`).join('')}</select></label>`:''}</div>${s.won?`<div class="win-banner" role="status">${esc(s.result)}</div>`:''}<div id="boardarea">${renderBoard(s)}</div><p class="game-note">${instructions(s)}</p>${s.id==='sprouts'?'<button id="concede" class="concede">No legal move · concede</button>':''}<div class="action-dock" role="group" aria-label="Game actions"><button id="undo" ${!history.length?'disabled':''}><span aria-hidden="true">↶</span> Undo</button><button id="hint"><span aria-hidden="true">✧</span> Hint</button><button id="restart"><span aria-hidden="true">↻</span> New game</button><button id="demo" ${DEMO_TEXT[s.id]?'':'hidden'}><span aria-hidden="true">${demoOn()?'■':'▶'}</span> ${demoOn()?'Stop':'Demo'}</button></div></section><aside class="aside"><div class="tip-box"><div class="eyebrow">A useful idea</div><h3>${esc(g.math)}</h3><p>${esc((L.variants?.[s.mode]||L).strategy[0])}</p><button id="open-strategy">Explore the strategy →</button><button id="open-research">Read the research →</button></div></aside></div>`;}
function cell(i,v,opts={}){return`<button class="cell ${opts.cls||''}" data-cell="${i}" ${opts.motion?`data-motion="${opts.motion}"`:""} aria-label="${esc(opts.label||'Square '+(i+1)+(v?' · '+v:''))}" ${opts.disabled?'disabled':''}>${v??''}</button>`;}
function grid(s,values,classes){return`<div class="board grid ${s.id==='sudoku'?'sudoku':''}" style="grid-template-columns:repeat(${s.cols},1fr)">${values.map((v,i)=>cell(i,v,{cls:classes?.(i)||'',motion:s.id==='sliding'&&v?'tile-'+v:null})).join('')}</div>`;}
function renderBoard(s){switch(s.id){
 case'hanoi':return`<div class="board hanoi">${s.stacks.map((st,i)=>`<button class="peg-tower ${selected===i?'sel':''}" data-peg="${i}" aria-label="Peg ${i+1}. ${st.length} disks">${st.slice().reverse().map(n=>`<span class="disk" data-motion="disk-${n}" style="width:${27+n*16}%;max-width:100%;background:${colors[n-1]}">${n}</span>`).join('')}<small style="position:absolute;bottom:-30px">${String.fromCharCode(65+i)}</small></button>`).join('')}</div>`;
 case'nim':{if(s.mode==='Kayles')return grid({cols:6},s.pins.map(v=>v?'●':''),i=>`${!s.pins[i]?'empty':''} ${pick?.pins?.includes(i)?'sel':''}`)+nimControls(s);
  return s.heaps.map((n,i)=>`<div class="heap ${pick?.heap===i?'sel':''}" data-heap="${i}" role="group" aria-label="Heap ${i+1}, ${n} counters"><strong>${n}</strong><span class="stones">${rangeUI(n).map(j=>`<button class="stone ${pick?.heap===i&&j>=n-pick.count?'taking':''} ${s.mode==='Grundy'&&pick?.heap===i&&j===n-pick.count?'cut':''}" data-stone="${i}:${j}" data-motion="counter-${i}-${j}" aria-label="${s.mode==='Grundy'?`Split heap ${i+1} into ${j} and ${n-j}`:`Take ${n-j} from heap ${i+1}`}"></button>`).join('')}</span><small>Heap ${i+1}</small></div>`).join('')+nimControls(s);}
 case'chomp':return grid(s,s.board.map((v,i)=>v?(i===0?'☠':''):' '),i=>s.board[i]?(i===0?'poison':''):'gone');
 case'domineering':return grid(s,s.board.map(v=>v?'':'·'),i=>s.board[i]?'p'+s.board[i]:'');
 case'clobber':return grid(s,s.board.map(v=>v?'●':''),i=>`${s.board[i]?'p'+s.board[i]:'empty'} ${selected===i?'sel':''} ${selected!=null&&E.move(s,{from:selected,to:i}).ok?'target':''}`);
 case'hackenbush':return`<div class="board"><svg class="game-svg" viewBox="0 0 360 320" aria-label="Hackenbush graph"><path d="M10 295H350" stroke="#95a779" stroke-width="6"/>${s.edges.filter(e=>e.live).map(e=>`<g data-cut="${e.id}" tabindex="0" role="button" aria-label="Cut ${e.color===1?'blue':'red'} edge ${e.id+1}"><line x1="${s.nodes[e.a].x}" y1="${s.nodes[e.a].y}" x2="${s.nodes[e.b].x}" y2="${s.nodes[e.b].y}" stroke="${colors[e.color-1]}" stroke-width="9" stroke-linecap="round"/><line x1="${s.nodes[e.a].x}" y1="${s.nodes[e.a].y}" x2="${s.nodes[e.b].x}" y2="${s.nodes[e.b].y}" stroke="transparent" stroke-width="54"/></g>`).join('')}</svg></div>`;
 case'sprouts':return`<div class="board"><svg id="sprouts-board" class="game-svg" viewBox="0 0 400 360" aria-label="Draw curves between dots">${s.edges.map(e=>`<polyline data-draw="${s.edges.indexOf(e)}" points="${e.path.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#547664" stroke-width="3"/>`).join('')}<polyline id="draft-curve" fill="none" stroke="#d76c51" stroke-width="3"/>${s.nodes.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="${p.d===3?6:9}" fill="${p.d===3?'#a6b49c':'#153d35'}"/><text x="${p.x+13}" y="${p.y-10}" font-size="11" fill="#647870">${i+1} · ${3-p.d} free</text>`).join('')}</svg></div>`;
 case'boxes':{let gap=90,pad=30;return`<div class="board"><svg class="game-svg" viewBox="0 0 330 330" aria-label="Dots and Boxes board">${Object.entries(s.boxes).map(([key,p])=>{let [r,c]=key.split(':').map(Number);return`<rect data-motion="box-${key}" x="${pad+c*gap+6}" y="${pad+r*gap+6}" width="78" height="78" rx="8" fill="${colors[p-1]}" opacity=".2"/><text x="${pad+c*gap+45}" y="${pad+r*gap+53}" text-anchor="middle" fill="${colors[p-1]}">${p}</text>`;}).join('')}${['h','v'].map(type=>rangeUI(type==='h'?4:3).map(r=>rangeUI(type==='h'?3:4).map(c=>{let x=pad+c*gap,y=pad+r*gap,key=type+':'+r+':'+c;return`<g data-line="${key}" tabindex="0" role="button" aria-label="${type==='h'?'Horizontal':'Vertical'} line row ${r+1}, column ${c+1}"><line ${s.edges[key]?`data-draw="${key}"`:""} x1="${x}" y1="${y}" x2="${x+(type==='h'?gap:0)}" y2="${y+(type==='v'?gap:0)}" stroke="${s.edges[key]?colors[s.edges[key]-1]:'#d9e1d1'}" stroke-width="${s.edges[key]?6:3}" stroke-linecap="round"/><line x1="${x}" y1="${y}" x2="${x+(type==='h'?gap:0)}" y2="${y+(type==='v'?gap:0)}" stroke="transparent" stroke-width="54"/></g>`;}).join('')).join('')).join('')}${rangeUI(4).map(r=>rangeUI(4).map(c=>`<circle cx="${pad+c*gap}" cy="${pad+r*gap}" r="5" fill="#153d35"/>`).join('')).join('')}</svg><div class="controls"><span class="player1">Blue ${s.scores[0]}</span> · <span class="player2">Red ${s.scores[1]}</span></div></div>`;}
 case'hex':return`<div class="board"><svg class="game-svg" viewBox="0 0 380 290" aria-label="Hex board. Blue connects top and bottom; red connects left and right."><path d="M25 12L266 12M114 276L360 276" stroke="${colors[0]}" stroke-width="5"/><path d="M13 35L95 255M282 30L367 247" stroke="${colors[1]}" stroke-width="5"/>${s.board.map((p,i)=>{let r=Math.floor(i/5),c=i%5,x=40+c*49+r*24.5,y=45+r*43;return`<polygon data-cell="${i}" tabindex="0" role="button" aria-label="Hex row ${r+1}, column ${c+1}${p?' player '+p:''}" points="${hexPoints(x,y,27)}" fill="${p?colors[p-1]:'#e8ecd9'}" stroke="#fffef9" stroke-width="3"/>`;}).join('')}</svg></div>`;
 case'sim':return`<div class="board"><svg class="game-svg" viewBox="0 0 400 385" aria-label="Six vertices. Choose two to color an edge.">${s.nodes.map((v,i)=>s.nodes.slice(0,i).map((w,j)=>`<line ${s.edges[j+':'+i]?`data-draw="${j}:${i}"`:""} x1="${v.x}" y1="${v.y}" x2="${w.x}" y2="${w.y}" stroke="${s.edges[j+':'+i]?colors[s.edges[j+':'+i]-1]:'#d9e1d1'}" stroke-width="${s.edges[j+':'+i]?5:1.5}"/>`).join('')).join('')}${s.nodes.map((v,i)=>`<g data-vertex="${i}" tabindex="0" role="button" aria-label="Vertex ${i+1}"><circle cx="${v.x}" cy="${v.y}" r="30" fill="transparent"/><circle cx="${v.x}" cy="${v.y}" r="${selected===i?19:15}" fill="${selected===i?'#d7b450':'#153d35'}"/><text x="${v.x}" y="${v.y+5}" text-anchor="middle" fill="#fff" font-size="13">${i+1}</text></g>`).join('')}</svg></div>`;
 case'peg':{let tri=s.mode==='Triangle';return`<div class="board"><svg class="game-svg" viewBox="0 0 ${tri?'330 300':'360 360'}" aria-label="Peg Solitaire board">${s.cells.map((v,i)=>{let x=tri?165+(v.c-v.r/2)*60:30+v.c*50,y=tri?30+v.r*60:30+v.r*50;return`<g data-hole="${i}" role="button" tabindex="0" aria-label="${v.v?'Peg':'Empty hole'} row ${v.r+1}, column ${v.c+1}"><circle cx="${x}" cy="${y}" r="27" fill="transparent"/><circle cx="${x}" cy="${y}" r="${selected===i?23:19}" fill="${selected===i?'#d7b450':v.v?'#153d35':'#dce3d0'}"/>${selected!=null&&!v.v&&E.move(s,{from:selected,to:i}).ok?`<circle class="target-ring" cx="${x}" cy="${y}" r="13" fill="none" stroke="#d7b450" stroke-width="3" stroke-dasharray="4 4"/>`:''}${v.v?`<circle cx="${x-4}" cy="${y-4}" r="7" fill="#789469"/>`:''}</g>`;}).join('')}</svg><div class="subtle" style="text-align:center">${s.cells.filter(v=>v.v).length} pegs remaining</div></div>`;}
 case'lights':return grid(s,s.board.map(v=>v?'✦':'·'),i=>s.board[i]?'':'empty');
 case'sliding':if(s.blocks)return`<div class="board"><svg class="game-svg" viewBox="0 0 ${s.cols*60} ${s.rows*60}" aria-label="Sliding block board"><rect width="100%" height="100%" rx="10" fill="#e9eedf"/>${s.blocks.map((b,i)=>`<g data-block="${i}" role="button" tabindex="0" aria-label="${b.target?'Target':('Block '+i)} at row ${b.r+1}, column ${b.c+1}"><rect x="${b.c*60+3}" y="${b.r*60+3}" width="${b.w*60-6}" height="${b.h*60-6}" rx="9" fill="${b.target?'#d76c51':colors[(i+2)%6]}" stroke="${selected===i?'#e7c868':'transparent'}" stroke-width="4"/><text x="${(b.c+b.w/2)*60}" y="${(b.r+b.h/2)*60+6}" text-anchor="middle" fill="#fff">${b.target?'★':i}</text></g>`).join('')}</svg><div class="controls">${['up','left','down','right'].map(d=>`<button data-direction="${d}" aria-label="Move ${d}">${{up:'↑',left:'←',down:'↓',right:'→'}[d]}</button>`).join('')}</div></div>`;return grid(s,s.board.map(v=>v||''),i=>s.board[i]?'':'empty');
 case'frogs':return grid({cols:7},s.board.map(v=>v===1?'▶':v===2?'◀':''),i=>s.board[i]?'p'+s.board[i]:'empty');
 case'sudoku':return grid(s,s.board.map(v=>v||''),i=>`${s.fixed[i]?'fixed':''} ${selected===i?'sel':''} ${s.board[i]&&!s.fixed[i]&&s.board[i]!==s.solution[i]?'error':''}`)+numberPad(9);
 case'nonogram':return`<div class="board nonogram" style="grid-template-columns:50px repeat(5,1fr)"><div></div>${s.colClues.map(c=>`<div class="clue">${c.join('\n')}</div>`).join('')}${rangeUI(5).map(r=>`<div class="clue">${s.rowClues[r].join(' ')}</div>${rangeUI(5).map(c=>{let i=r*5+c;return cell(i,s.board[i]===-1?'×':'',{cls:s.board[i]===1?'p1':'empty'});}).join('')}`).join('')}</div><div class="controls"><button data-brush="1" class="${brush===1?'primary':''}">Fill</button><button data-brush="-1" class="${brush===-1?'primary':''}">Mark empty</button></div>`;
 case'kakuro':return`<div class="board grid" style="grid-template-columns:repeat(4,1fr)"><div class="clue">Σ</div>${s.colClues.map(v=>`<div class="clue">↓ ${v}</div>`).join('')}${rangeUI(3).map(r=>`<div class="clue">→ ${s.rowClues[r]}</div>${rangeUI(3).map(c=>{let i=r*3+c;return cell(i,s.board[i]||'',{cls:selected===i?'sel':''});}).join('')}`).join('')}</div>${numberPad(9)}`;
 case'mastermind':return`<div class="board">${s.guesses.map((g,i)=>`<div class="guess-row"><small>${i+1}</small>${g.guess.map(v=>`<span class="color-dot" style="background:${colors[v]}"></span>`).join('')}<span class="guess-feedback">${g.exact} exact<br>${g.partial} color only</span></div>`).join('')}${s.won?`<p class="subtle">Secret code:</p><div class="guess-row">${s.secret.map(v=>`<span class="color-dot" style="background:${colors[v]}"></span>`).join('')}</div>`:`<p class="subtle" style="text-align:center">Pick a slot, then a color. The next slot is chosen for you.</p><div class="guess-row">${guess.map((v,i)=>`<button class="color-dot ${slot===i?'active':''}" data-guess="${i}" style="background:${colors[v]}" aria-pressed="${slot===i}" aria-label="Slot ${i+1}, ${COLOR_NAMES[v]}"></button>`).join('')}</div><div class="palette" role="group" aria-label="Colors">${colors.map((c,k)=>`<button class="swatch" data-color-pick="${k}" style="background:${c}" aria-label="${COLOR_NAMES[k]}"></button>`).join('')}</div><div class="controls"><button class="primary" id="submit-guess">Check guess</button>${s.guesses.length===0?'<button id="set-secret">Set secret · 2 players</button>':''}</div>`}</div>`;
 case'set':return`<div class="board"><div class="subtle" style="text-align:center;margin-bottom:15px">${s.found} / ${s.goal} SETs found · ${s.deck.length} cards in deck</div><div class="set-cards">${s.hand.map((a,i)=>`<button class="set-card ${cardsSelected.includes(i)?'sel':''}" data-card="${i}" data-motion="card-${a.join('')}" aria-label="Card ${i+1}: ${a[2]+1} ${['ovals','diamonds','rectangles'][a[1]]}, ${['blue','red','green'][a[0]]}, ${['solid','striped','outline'][a[3]]}">${setCard(a,i)}</button>`).join('')}</div><div class="controls"><button id="add-cards">No SET? Add 3 cards</button></div></div>`;
 case'queens':{let conflict=E.queenConflicts(s);return grid(s,s.board.map(v=>v?'♛':''),i=>`${(Math.floor(i/s.cols)+i%s.cols)%2?'':'fixed'} ${conflict.includes(i)?'error':''}`)+`<p class="subtle" style="text-align:center">${s.board.filter(Boolean).length} / ${s.rows} queens · ${conflict.length} attacking queens</p>`;}
 case'tangram':return`<div class="board" style="max-width:500px"><svg id="tangram-board" class="game-svg" viewBox="0 0 500 420" aria-label="Tangram square target and seven draggable pieces"><rect x="140" y="80" width="200" height="200" fill="#e8ecd9" stroke="#a4b08c" stroke-dasharray="6 6" stroke-width="2"/>${s.guide?s.pieces.map(b=>`<polygon points="${E.piecePoly({...b,x:b.target[0],y:b.target[1],angle:0,flip:false}).map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#a4b08c" stroke-width="1.5"/>`).join(''):''}${s.pieces.map((b,i)=>`<polygon data-piece="${i}" points="${E.piecePoly(b).map(p=>p.x+','+p.y).join(' ')}" fill="${colors[i%6]}" fill-opacity=".85" stroke="${selected===i?'#e7c868':'#fffef9'}" stroke-width="${selected===i?4:2}" tabindex="0" role="button" aria-label="Tangram piece ${i+1}"/>`).join('')}<circle id="snap-mark" r="7" fill="none" stroke="#e4b85a" stroke-width="3"/></svg><div class="controls"><button id="rotate">Rotate 45°</button><button id="flip">Flip</button><button id="guide">${s.guide?'Hide':'Show'} guide</button></div></div>`;
 case'rubik':return Cube3D.render(s);
 case'river':return riverBoard(s);
 case'twentyfour':return`<div class="board"><div class="four-numbers">${s.numbers.map(n=>`<span>${n}</span>`).join('')}</div><label class="subtle" for="expression">Your expression</label><input class="expression" id="expression" placeholder="Tap numbers and signs" autocomplete="off" inputmode="none"><div class="keypad24" role="group" aria-label="Expression keys">${s.numbers.map((n,k)=>`<button class="num" data-key24="${n}" data-num-index="${k}">${n}</button>`).join('')}${['+','−','×','÷','(',')'].map(k=>`<button data-key24="${k}" aria-label="${({'+':'plus','−':'minus','×':'times','÷':'divided by','(':'open bracket',')':'close bracket'})[k]}">${k}</button>`).join('')}<button data-key24="back" aria-label="Delete last">⌫</button><button data-key24="clear" aria-label="Clear">C</button></div><div class="controls"><button id="check24" class="primary">Make 24</button></div><p class="subtle">Each number can be used once. A keyboard works too: * means × and / means ÷.</p></div>`;
 }return'';}
const RIVER_ICONS={
 farmer:'<circle cx="20" cy="15" r="7" fill="#e3ad84"/><path d="M8 13h24l-4-3h-4l-1-5h-6l-1 5h-4Z" fill="#d7b450"/><path d="M9 38c0-9 5-14 11-14s11 5 11 14Z" fill="#3d86ab"/><path d="M15 25l5 6 5-6" fill="none" stroke="#2e5751" stroke-width="2"/>',
 wolf:'<path d="M7 6l8 8h10l8-8 1 16-6 10-8 4-8-4-6-10Z" fill="#7b8894"/><path d="M14 26l6 9 6-9Z" fill="#d9dee2"/><circle cx="15" cy="20" r="2" fill="#163c35"/><circle cx="25" cy="20" r="2" fill="#163c35"/><circle cx="20" cy="31" r="2.2" fill="#163c35"/>',
 goat:'<path d="M12 12C8 4 4 6 3 9M28 12c4-8 8-6 9-3" fill="none" stroke="#a48b6a" stroke-width="3" stroke-linecap="round"/><path d="M5 15l7-2 4 3Zm30 0-7-2-4 3Z" fill="#e8dfcf"/><ellipse cx="20" cy="21" rx="9" ry="12" fill="#f4eee2" stroke="#cbbfa8" stroke-width="1.5"/><path d="M17 33l3 6 3-6Z" fill="#cbbfa8"/><circle cx="16" cy="19" r="1.8" fill="#163c35"/><circle cx="24" cy="19" r="1.8" fill="#163c35"/>',
 cabbage:'<circle cx="20" cy="22" r="14" fill="#9dba68"/><path d="M20 9c-7 5-7 21 0 27M20 9c7 5 7 21 0 27M7 19c6 2 10 6 13 17m13-17c-6 2-10 6-13 17" fill="none" stroke="#e8f0d4" stroke-width="1.8"/><circle cx="20" cy="22" r="6" fill="#bfd68d"/>',
 person:c=>`<circle cx="20" cy="12" r="7" fill="#e3ad84"/><path d="M8 38c0-10 5-16 12-16s12 6 12 16Z" fill="${c}"/>`};
// Both puzzles use the same scene. Each passenger keeps one row on both banks,
// so the people who cross move straight across. Tapping a passenger on the
// boat's bank seats them; tapping the boat rows across.
let riverLoad={key:'',ids:[]};
function riverKey(s){return s.mode+JSON.stringify(s.mode==='Farmer'?s.banks:[s.left,s.boat]);}
function riverTokens(s){
 if(s.mode==='Farmer')return['Farmer','Wolf','Goat','Cabbage'].map((name,i)=>({id:name.toLowerCase(),name,cargo:i,bank:s.banks[i],row:i+1,col:1,icon:RIVER_ICONS[name.toLowerCase()]}));
 return[0,1,2].flatMap(k=>[{id:'missionary-'+k,name:'Missionary',letter:'M',bank:k<s.left[0]?0:1,row:k+1,col:1,icon:RIVER_ICONS.person('#3d86ab')},{id:'cannibal-'+k,name:'Cannibal',letter:'C',bank:k<s.left[1]?0:1,row:k+1,col:2,icon:RIVER_ICONS.person('#d76c51')}]);
}
function riverBoard(s){
 const farmer=s.mode==='Farmer',side=farmer?s.banks[0]:s.boat,rows=farmer?4:3,tokens=riverTokens(s);
 if(riverLoad.key!==riverKey(s))riverLoad={key:riverKey(s),ids:[]};
 const seated=t=>farmer&&t.id==='farmer'||riverLoad.ids.includes(t.id);
 const token=(t,inBoat)=>`<button class="river-token ${!inBoat&&t.bank!==side?'far':''}" ${t.id==='farmer'?'data-sail':`data-board="${t.id}"`} data-motion="${t.id}" style="grid-row:${t.row};grid-column:${t.col}" aria-label="${inBoat?(t.id==='farmer'?'Farmer at the oars. Tap to cross':t.name+' in the boat. Tap to step out'):t.name+(t.bank===side?'. Tap to board':' on the far bank')}"><svg viewBox="0 0 40 40" aria-hidden="true">${t.icon}</svg>${farmer?`<small>${t.name}</small>`:`<b>${t.letter}</b>`}</button>`;
 const bank=b=>`<div class="bank bank-${b?'right':'left'}" role="group" aria-label="${b?'Destination':'Starting'} bank" style="grid-template-rows:repeat(${rows},minmax(0,1fr));grid-template-columns:repeat(${farmer?1:2},minmax(0,1fr))">${tokens.filter(t=>t.bank===b&&!seated(t)).map(t=>token(t,false)).join('')}</div>`;
 const aboard=tokens.filter(seated),names=aboard.map(t=>t.name.toLowerCase()).join(' and ')||'nobody';
 return`<div class="board river"><div class="river-scene ${farmer?'':'river-crowd'}">${bank(0)}<div class="river-channel"><div class="boat ${side?'docked-right':'docked-left'}" data-motion="boat"><div class="boat-seats">${aboard.map(t=>token(t,true)).join('')}</div><button class="boat-hull" data-sail aria-label="Row across with ${names}"><svg viewBox="0 0 100 34" aria-hidden="true"><path d="M2 8h96L84 30H16Z" fill="#8a5a3b"/><path d="M2 8h96" stroke="#6b4329" stroke-width="5" stroke-linecap="round"/><path d="M14 18h72" stroke="#a7724f" stroke-width="2"/></svg><span>${side?'← Row':'Row →'}</span></button></div></div>${bank(1)}</div><div class="river-captions"><span>Start</span><span>${farmer?'Tap who rides with the farmer':'Tap one or two to board'}, then the boat</span><span>Goal</span></div></div>`;}
function boardRiver(id){
 const s=current,farmer=s.mode==='Farmer',side=farmer?s.banks[0]:s.boat,tokens=riverTokens(s);if(s.won)return;
 const t=tokens.find(x=>x.id===id);if(!t)return;
 if(riverLoad.ids.includes(id))riverLoad.ids=riverLoad.ids.filter(x=>x!==id);
 else if(t.bank!==side){toast(`The ${t.name.toLowerCase()} is on the other bank. The boat must go to fetch them.`);GameMotion.reject($('#boardarea'));return;}
 else if(farmer)riverLoad.ids=[id];// One passenger rides with the farmer.
 else{
  if(riverLoad.ids.length>=2){toast('The boat holds two people. Tap someone in the boat to let them off.');GameMotion.reject($('#boardarea'));return;}
  // Identical travellers: board the next one of that kind so identities stay stable.
  const kind=id.split('-')[0],free=tokens.filter(x=>x.id.startsWith(kind)&&x.bank===side&&!riverLoad.ids.includes(x.id)).map(x=>+x.id.split('-')[1]);
  riverLoad.ids.push(kind+'-'+(side===0?Math.max(...free):Math.min(...free)));
 }
 relayout();
}
function sailRiver(){
 const s=current;if(s.won)return;
 if(s.mode==='Farmer'){const cargo=riverLoad.ids.length?['farmer','wolf','goat','cabbage'].indexOf(riverLoad.ids[0]):-1;transact({cargo});return;}
 if(!riverLoad.ids.length){toast('Tap one or two people to board first.');GameMotion.reject($('#boardarea'));return;}
 transact({m:riverLoad.ids.filter(x=>x.startsWith('missionary')).length,c:riverLoad.ids.filter(x=>x.startsWith('cannibal')).length});
}
// Re-render for a change that is not a move (boarding, selections) and glide pieces to their new places.
function relayout(){const before=GameMotion.snapshot($('#boardarea'));GameMotion.cancel();renderGame();GameMotion.relayout(before,$('#boardarea'));}
function numberPad(n){return`<div class="number-pad">${rangeUI(n).map(i=>`<button data-number="${i+1}">${i+1}</button>`).join('')}<button data-number="0">Erase</button></div>`;}
function nimControls(s){const kay=s.mode==='Kayles',n=kay?pick?.pins?.length:pick?.count,size=pick&&!kay?s.heaps[pick.heap]:0,label=!pick?(kay?'Tap a pin':s.mode==='Grundy'?'Tap where to split':'Tap a counter'):kay?`Remove ${n} pin${n>1?'s':''}`:s.mode==='Grundy'?`Split into ${size-n} and ${n}`:`Take ${n}`;return`<div class="controls"><button id="take" class="primary" ${pick?'':'disabled'}>${label}</button>${s.mode==='Wythoff'?`<button id="take-both" ${pick?'':'disabled'}>${pick?`Take ${n} from both`:'From both heaps'}</button>`:''}</div><p class="subtle nim-help">${kay?'Tap a pin; tap a neighbour too to knock down a pair.':s.mode==='Grundy'?'Tap a counter to split the heap there.':'Tap a counter: it and every counter to its right will be taken.'}${s.mode==='Fibonacci Nim'?` You may take at most ${s.limit} this turn.`:''}</p>`;}
function setCard(a,i){let color=['#3d86ab','#d76c51','#5f8d5d'][a[0]],fill=a[3]===0?color:a[3]===1?`url(#stripe${i})`:'none';return`<svg viewBox="0 0 110 60" aria-hidden="true"><defs><pattern id="stripe${i}" patternUnits="userSpaceOnUse" width="5" height="5"><path d="M0 0V5" stroke="${color}" stroke-width="2"/></pattern></defs>${rangeUI(a[2]+1).map(j=>{let x=55+(j-a[2]/2)*30;return a[1]===0?`<ellipse cx="${x}" cy="30" rx="10" ry="21" fill="${fill}" stroke="${color}" stroke-width="2"/>`:a[1]===1?`<polygon points="${x},8 ${x+12},30 ${x},52 ${x-12},30" fill="${fill}" stroke="${color}" stroke-width="2"/>`:`<rect x="${x-10}" y="9" width="20" height="42" rx="4" fill="${fill}" stroke="${color}" stroke-width="2"/>`;}).join('')}</svg>`;}
function instructions(s){let texts={hanoi:'Tap the source peg, then the destination. Move the full stack to the rightmost peg.',nim:s.mode==='Kayles'?'Tap a standing pin (and a neighbour for a pair), then Remove.':s.mode==='Grundy'?'Tap a counter to split its heap there. Both parts must be nonempty and unequal.':'Tap a counter to take it and every counter to its right, then confirm.',chomp:'Tap a square to remove it and all squares below and to its right. The top-left square is poisoned.',domineering:'Blue places vertical dominoes; red places horizontal ones. Tap either square the domino should cover.',clobber:'Tap your piece, then an adjacent opponent piece to capture it.',hackenbush:'Blue cuts blue edges; red cuts red edges. Unsupported edges disappear.',sprouts:'Draw with your finger from a dot to another dot, or back to itself. Curves must not cross. Each dot allows three line ends.',boxes:'Tap between adjacent dots. Closing a box gives you a point and another turn.',hex:'Blue connects top to bottom; red connects left to right. Tap an empty hexagon.',sim:'Select two vertices to color their edge. Completing a triangle in your own color loses.',peg:'Tap a peg, then an empty hole two steps away to jump over and remove one peg.',lights:'Tap a light to toggle it and its orthogonal neighbors. Turn them all off.',sliding:s.blocks?'Swipe a block to slide it (a longer swipe moves it further), or select it and use the arrows. The red target must reach the exit.':'Tap any tile in the same row or column as the gap to slide it, with any tiles between. Arrange tiles in order, with the gap last.',frogs:'Blue toads move right; red frogs move left. Slide into the gap or jump over one opposing piece.',sudoku:'Select an empty cell, then choose a digit. Red cells disagree with this puzzle’s solution.',nonogram:'The clues give consecutive filled runs. Separate runs by at least one empty square.',kakuro:'Choose a cell and enter 1–9. Meet each row and column sum without repeating a digit in that run. Any valid filling wins.',mastermind:'Choose a slot, then a color, for all four slots, and check. “Exact” means right color and position; “color only” means wrong position.',set:'Select three cards. Color, shape, count, and shading must each be all the same or all different.',queens:'Tap to add or remove queens. Place '+s.rows+' queens with no shared row, column, or diagonal.',tangram:'Drag the seven pieces into the shaded square. Corners click into place on the grid and against other pieces. Tap a selected piece to turn it 45°; use Flip for the parallelogram.',rubik:'Swipe across a row or column of the cube to turn it, middle rows included. Drag beside the cube to look around. The side keys turn whole faces: U up, F front, R right, D down, B back, L left; ↻ switches to counterclockwise (′).',river:s.mode==='Farmer'?'Tap the wolf, goat or cabbage to seat it beside the farmer (or nobody), then tap the boat to row. Never leave the wolf with the goat, or the goat with the cabbage, without the farmer.':'Tap one or two people on the boat’s bank to seat them, then tap the boat. Missionaries may never be outnumbered by cannibals on either bank.',twentyfour:'Tap the numbers and signs to build an expression using every number exactly once, then tap Make 24.'};return texts[s.id];}
